"""Generated by tools/gen_voxel_asm.py from turbo_source/voxel.py's F_* slots: edit those.

frame_asm(args_address) renders a whole VoxelSpace frame, the same pixels as
voxel.render(). Relabelled as viper by tools/asm_to_viper.py, so the argument
object is at [r3]. Specialised for a 512-texel map and a 320-wide back buffer.
"""

import micropython


@micropython.asm_thumb
def frame_asm(r0, r1, r2, r3):
    # r7: args. Row loop: r0 px, r1 py, r2 column buffer pointer,
    # r8 dx, r9 dy, r10 terrain level, r11 hinvz, r12 C (see voxel.F_HORIZON).
    ldr(r7, [r3, 0])
    push({r7})
    asr(r7, r7, 1)
    mov(r3, r8)  # r8-r11 belong to the caller
    mov(r4, r9)
    mov(r5, r10)
    mov(r6, r11)
    push({r3, r4, r5, r6})

    # every column starts empty
    ldr(r2, [r7, 8])
    ldr(r3, [r7, 12])
    ldr(r4, [r7, 100])
    label(clear)
    str(r4, [r2, 0])
    add(r2, r2, 4)
    cmp(r2, r3)
    blt(clear)

    ldr(r6, [r7, 40])
    str(r6, [r7, 48])
    label(row)
    ldr(r6, [r7, 48])
    ldr(r0, [r6, 0])  # z
    ldr(r2, [r7, 60])
    mul(r2, r0)
    ldr(r3, [r7, 52])
    add(r2, r2, r3)
    lsl(r2, r2, 7)
    str(r2, [r7, 0])
    ldr(r2, [r7, 64])
    mul(r2, r0)
    ldr(r3, [r7, 56])
    add(r2, r2, r3)
    lsl(r2, r2, 7)
    str(r2, [r7, 4])
    ldr(r2, [r7, 68])
    mul(r2, r0)
    lsl(r2, r2, 7)
    mov(r8, r2)
    ldr(r2, [r7, 72])
    mul(r2, r0)
    lsl(r2, r2, 7)
    mov(r9, r2)
    ldr(r0, [r6, 4])  # invz
    ldr(r2, [r7, 76])
    mul(r2, r0)
    ldr(r3, [r7, 104])
    mul(r3, r0)
    lsr(r3, r3, 8)
    add(r2, r2, r3)
    ldr(r3, [r7, 80])
    add(r2, r2, r3)
    # terrain heights scaled around the base: hinvz = invz >> shift, and
    # C -= base * (invz - hinvz)
    ldr(r3, [r7, 108])
    mov(r4, r0)
    lsr(r4, r3)
    mov(r11, r4)
    sub(r3, r0, r4)
    ldr(r5, [r7, 112])
    mul(r3, r5)
    sub(r2, r2, r3)
    mov(r12, r2)
    ldr(r0, [r6, 8])  # fog
    mov(r2, 32)
    sub(r2, r2, r0)
    str(r2, [r7, 24])
    ldr(r2, [r7, 84])
    mul(r2, r0)
    str(r2, [r7, 28])
    ldr(r3, [r6, 12])  # mip level
    add(r6, 16)
    str(r6, [r7, 48])
    mov(r5, r0)
    ldr(r0, [r7, 0])
    ldr(r1, [r7, 4])
    ldr(r2, [r7, 8])
    # pick the loop for this level and fog (conditional branches only reach
    # 256 bytes, so they go through nearby unconditional ones)
    cmp(r5, 0)
    bne(fogged)
    cmp(r3, 1)
    blt(to0)
    beq(to1)
    b(enter2)
    label(to0)
    b(enter0)
    label(to1)
    b(enter1)
    label(fogged)
    cmp(r3, 1)
    blt(to0f)
    beq(to1f)
    b(enter2f)
    label(to0f)
    b(enter0f)
    label(to1f)
    b(enter1f)

    label(enter0)
    ldr(r3, [r7, 88])
    mov(r10, r3)
    label(sample0)
    # texel: level + (py >> 23) * 1024 + (px >> 23) * 2
    lsr(r3, r0, 23)
    lsl(r3, r3, 1)
    lsr(r4, r1, 23)
    lsl(r4, r4, 10)
    add(r3, r3, r4)
    mov(r4, r10)
    add(r3, r3, r4)
    ldrh(r3, [r3, 0])  # height << 8 | palette index
    # top = (C - height * hinvz) >> 12
    lsr(r4, r3, 8)
    mov(r5, r11)
    mul(r4, r5)
    mov(r5, r12)
    sub(r4, r5, r4)
    asr(r4, r4, 12)
    ldr(r5, [r2, 0])  # bottom: the column's highest pixel so far
    cmp(r4, r5)
    bge(next0)
    cmp(r4, 0)
    bge(on_screen0)
    mov(r4, 0)
    label(on_screen0)
    str(r4, [r2, 0])
    # palette color, already spread to 0x07E0F81F form
    lsl(r3, r3, 24)
    lsr(r3, r3, 22)
    ldr(r6, [r7, 36])
    add(r3, r3, r6)
    ldr(r3, [r3, 0])
    lsr(r6, r3, 16)
    orr(r3, r6)  # rgb565 in the low half
    # first pixel: back + column * 2 + top * 640
    ldr(r6, [r7, 8])
    sub(r6, r2, r6)
    lsr(r6, r6, 1)
    sub(r5, r5, r4)  # pixels to fill
    lsl(r4, r4, 7)
    add(r6, r6, r4)
    lsl(r4, r4, 2)
    add(r6, r6, r4)
    ldr(r4, [r7, 16])
    add(r6, r6, r4)
    movw(r4, 640)
    label(fill0)
    strh(r3, [r6, 0])
    add(r6, r6, r4)
    sub(r5, r5, 1)
    bgt(fill0)
    label(next0)
    mov(r3, r8)
    add(r0, r0, r3)
    mov(r3, r9)
    add(r1, r1, r3)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sample0)
    b(row_done)

    label(enter1)
    ldr(r3, [r7, 92])
    mov(r10, r3)
    label(sample1)
    # texel: level + (py >> 24) * 512 + (px >> 24) * 2
    lsr(r3, r0, 24)
    lsl(r3, r3, 1)
    lsr(r4, r1, 24)
    lsl(r4, r4, 9)
    add(r3, r3, r4)
    mov(r4, r10)
    add(r3, r3, r4)
    ldrh(r3, [r3, 0])  # height << 8 | palette index
    # top = (C - height * hinvz) >> 12
    lsr(r4, r3, 8)
    mov(r5, r11)
    mul(r4, r5)
    mov(r5, r12)
    sub(r4, r5, r4)
    asr(r4, r4, 12)
    ldr(r5, [r2, 0])  # bottom: the column's highest pixel so far
    cmp(r4, r5)
    bge(next1)
    cmp(r4, 0)
    bge(on_screen1)
    mov(r4, 0)
    label(on_screen1)
    str(r4, [r2, 0])
    # palette color, already spread to 0x07E0F81F form
    lsl(r3, r3, 24)
    lsr(r3, r3, 22)
    ldr(r6, [r7, 36])
    add(r3, r3, r6)
    ldr(r3, [r3, 0])
    lsr(r6, r3, 16)
    orr(r3, r6)  # rgb565 in the low half
    # first pixel: back + column * 2 + top * 640
    ldr(r6, [r7, 8])
    sub(r6, r2, r6)
    lsr(r6, r6, 1)
    sub(r5, r5, r4)  # pixels to fill
    lsl(r4, r4, 7)
    add(r6, r6, r4)
    lsl(r4, r4, 2)
    add(r6, r6, r4)
    ldr(r4, [r7, 16])
    add(r6, r6, r4)
    movw(r4, 640)
    label(fill1)
    strh(r3, [r6, 0])
    add(r6, r6, r4)
    sub(r5, r5, 1)
    bgt(fill1)
    label(next1)
    mov(r3, r8)
    add(r0, r0, r3)
    mov(r3, r9)
    add(r1, r1, r3)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sample1)
    b(row_done)

    label(enter2)
    ldr(r3, [r7, 96])
    mov(r10, r3)
    label(sample2)
    # texel: level + (py >> 25) * 256 + (px >> 25) * 2
    lsr(r3, r0, 25)
    lsl(r3, r3, 1)
    lsr(r4, r1, 25)
    lsl(r4, r4, 8)
    add(r3, r3, r4)
    mov(r4, r10)
    add(r3, r3, r4)
    ldrh(r3, [r3, 0])  # height << 8 | palette index
    # top = (C - height * hinvz) >> 12
    lsr(r4, r3, 8)
    mov(r5, r11)
    mul(r4, r5)
    mov(r5, r12)
    sub(r4, r5, r4)
    asr(r4, r4, 12)
    ldr(r5, [r2, 0])  # bottom: the column's highest pixel so far
    cmp(r4, r5)
    bge(next2)
    cmp(r4, 0)
    bge(on_screen2)
    mov(r4, 0)
    label(on_screen2)
    str(r4, [r2, 0])
    # palette color, already spread to 0x07E0F81F form
    lsl(r3, r3, 24)
    lsr(r3, r3, 22)
    ldr(r6, [r7, 36])
    add(r3, r3, r6)
    ldr(r3, [r3, 0])
    lsr(r6, r3, 16)
    orr(r3, r6)  # rgb565 in the low half
    # first pixel: back + column * 2 + top * 640
    ldr(r6, [r7, 8])
    sub(r6, r2, r6)
    lsr(r6, r6, 1)
    sub(r5, r5, r4)  # pixels to fill
    lsl(r4, r4, 7)
    add(r6, r6, r4)
    lsl(r4, r4, 2)
    add(r6, r6, r4)
    ldr(r4, [r7, 16])
    add(r6, r6, r4)
    movw(r4, 640)
    label(fill2)
    strh(r3, [r6, 0])
    add(r6, r6, r4)
    sub(r5, r5, 1)
    bgt(fill2)
    label(next2)
    mov(r3, r8)
    add(r0, r0, r3)
    mov(r3, r9)
    add(r1, r1, r3)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sample2)
    b(row_done)

    label(enter0f)
    ldr(r3, [r7, 88])
    mov(r10, r3)
    label(sample0f)
    # texel: level + (py >> 23) * 1024 + (px >> 23) * 2
    lsr(r3, r0, 23)
    lsl(r3, r3, 1)
    lsr(r4, r1, 23)
    lsl(r4, r4, 10)
    add(r3, r3, r4)
    mov(r4, r10)
    add(r3, r3, r4)
    ldrh(r3, [r3, 0])  # height << 8 | palette index
    # top = (C - height * hinvz) >> 12
    lsr(r4, r3, 8)
    mov(r5, r11)
    mul(r4, r5)
    mov(r5, r12)
    sub(r4, r5, r4)
    asr(r4, r4, 12)
    ldr(r5, [r2, 0])  # bottom: the column's highest pixel so far
    cmp(r4, r5)
    bge(next0f)
    cmp(r4, 0)
    bge(on_screen0f)
    mov(r4, 0)
    label(on_screen0f)
    str(r4, [r2, 0])
    # palette color, already spread to 0x07E0F81F form
    lsl(r3, r3, 24)
    lsr(r3, r3, 22)
    ldr(r6, [r7, 36])
    add(r3, r3, r6)
    ldr(r3, [r3, 0])
    # blended toward the fog color
    ldr(r6, [r7, 24])
    mul(r3, r6)
    ldr(r6, [r7, 28])
    add(r3, r3, r6)
    lsr(r3, r3, 5)
    ldr(r6, [r7, 20])
    and_(r3, r6)
    lsr(r6, r3, 16)
    orr(r3, r6)  # rgb565 in the low half
    # first pixel: back + column * 2 + top * 640
    ldr(r6, [r7, 8])
    sub(r6, r2, r6)
    lsr(r6, r6, 1)
    sub(r5, r5, r4)  # pixels to fill
    lsl(r4, r4, 7)
    add(r6, r6, r4)
    lsl(r4, r4, 2)
    add(r6, r6, r4)
    ldr(r4, [r7, 16])
    add(r6, r6, r4)
    movw(r4, 640)
    label(fill0f)
    strh(r3, [r6, 0])
    add(r6, r6, r4)
    sub(r5, r5, 1)
    bgt(fill0f)
    label(next0f)
    mov(r3, r8)
    add(r0, r0, r3)
    mov(r3, r9)
    add(r1, r1, r3)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sample0f)
    b(row_done)

    label(enter1f)
    ldr(r3, [r7, 92])
    mov(r10, r3)
    label(sample1f)
    # texel: level + (py >> 24) * 512 + (px >> 24) * 2
    lsr(r3, r0, 24)
    lsl(r3, r3, 1)
    lsr(r4, r1, 24)
    lsl(r4, r4, 9)
    add(r3, r3, r4)
    mov(r4, r10)
    add(r3, r3, r4)
    ldrh(r3, [r3, 0])  # height << 8 | palette index
    # top = (C - height * hinvz) >> 12
    lsr(r4, r3, 8)
    mov(r5, r11)
    mul(r4, r5)
    mov(r5, r12)
    sub(r4, r5, r4)
    asr(r4, r4, 12)
    ldr(r5, [r2, 0])  # bottom: the column's highest pixel so far
    cmp(r4, r5)
    bge(next1f)
    cmp(r4, 0)
    bge(on_screen1f)
    mov(r4, 0)
    label(on_screen1f)
    str(r4, [r2, 0])
    # palette color, already spread to 0x07E0F81F form
    lsl(r3, r3, 24)
    lsr(r3, r3, 22)
    ldr(r6, [r7, 36])
    add(r3, r3, r6)
    ldr(r3, [r3, 0])
    # blended toward the fog color
    ldr(r6, [r7, 24])
    mul(r3, r6)
    ldr(r6, [r7, 28])
    add(r3, r3, r6)
    lsr(r3, r3, 5)
    ldr(r6, [r7, 20])
    and_(r3, r6)
    lsr(r6, r3, 16)
    orr(r3, r6)  # rgb565 in the low half
    # first pixel: back + column * 2 + top * 640
    ldr(r6, [r7, 8])
    sub(r6, r2, r6)
    lsr(r6, r6, 1)
    sub(r5, r5, r4)  # pixels to fill
    lsl(r4, r4, 7)
    add(r6, r6, r4)
    lsl(r4, r4, 2)
    add(r6, r6, r4)
    ldr(r4, [r7, 16])
    add(r6, r6, r4)
    movw(r4, 640)
    label(fill1f)
    strh(r3, [r6, 0])
    add(r6, r6, r4)
    sub(r5, r5, 1)
    bgt(fill1f)
    label(next1f)
    mov(r3, r8)
    add(r0, r0, r3)
    mov(r3, r9)
    add(r1, r1, r3)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sample1f)
    b(row_done)

    label(enter2f)
    ldr(r3, [r7, 96])
    mov(r10, r3)
    label(sample2f)
    # texel: level + (py >> 25) * 256 + (px >> 25) * 2
    lsr(r3, r0, 25)
    lsl(r3, r3, 1)
    lsr(r4, r1, 25)
    lsl(r4, r4, 8)
    add(r3, r3, r4)
    mov(r4, r10)
    add(r3, r3, r4)
    ldrh(r3, [r3, 0])  # height << 8 | palette index
    # top = (C - height * hinvz) >> 12
    lsr(r4, r3, 8)
    mov(r5, r11)
    mul(r4, r5)
    mov(r5, r12)
    sub(r4, r5, r4)
    asr(r4, r4, 12)
    ldr(r5, [r2, 0])  # bottom: the column's highest pixel so far
    cmp(r4, r5)
    bge(next2f)
    cmp(r4, 0)
    bge(on_screen2f)
    mov(r4, 0)
    label(on_screen2f)
    str(r4, [r2, 0])
    # palette color, already spread to 0x07E0F81F form
    lsl(r3, r3, 24)
    lsr(r3, r3, 22)
    ldr(r6, [r7, 36])
    add(r3, r3, r6)
    ldr(r3, [r3, 0])
    # blended toward the fog color
    ldr(r6, [r7, 24])
    mul(r3, r6)
    ldr(r6, [r7, 28])
    add(r3, r3, r6)
    lsr(r3, r3, 5)
    ldr(r6, [r7, 20])
    and_(r3, r6)
    lsr(r6, r3, 16)
    orr(r3, r6)  # rgb565 in the low half
    # first pixel: back + column * 2 + top * 640
    ldr(r6, [r7, 8])
    sub(r6, r2, r6)
    lsr(r6, r6, 1)
    sub(r5, r5, r4)  # pixels to fill
    lsl(r4, r4, 7)
    add(r6, r6, r4)
    lsl(r4, r4, 2)
    add(r6, r6, r4)
    ldr(r4, [r7, 16])
    add(r6, r6, r4)
    movw(r4, 640)
    label(fill2f)
    strh(r3, [r6, 0])
    add(r6, r6, r4)
    sub(r5, r5, 1)
    bgt(fill2f)
    label(next2f)
    mov(r3, r8)
    add(r0, r0, r3)
    mov(r3, r9)
    add(r1, r1, r3)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sample2f)
    b(row_done)

    label(row_done)
    ldr(r6, [r7, 48])
    ldr(r3, [r7, 44])
    cmp(r6, r3)
    bge(sky)
    b(row)

    # sky in whatever each column has left
    label(sky)
    ldr(r2, [r7, 8])
    ldr(r1, [r7, 16])
    movw(r6, 640)
    label(sky_column)
    ldr(r3, [r2, 0])
    cmp(r3, 0)
    ble(sky_next)
    ldr(r4, [r7, 32])
    mov(r5, r1)
    label(sky_fill)
    ldr(r0, [r4, 0])
    strh(r0, [r5, 0])
    add(r4, 4)
    add(r5, r5, r6)
    sub(r3, r3, 1)
    bgt(sky_fill)
    label(sky_next)
    add(r1, r1, 2)
    add(r2, r2, 4)
    ldr(r3, [r7, 12])
    cmp(r2, r3)
    blt(sky_column)

    pop({r3, r4, r5, r6})
    mov(r8, r3)
    mov(r9, r4)
    mov(r10, r5)
    mov(r11, r6)
    pop({r0})
